// Corrects four existing Thai glossary entries. These are OVERWRITES, not fills,
// so each carries the exact value it expects to find; the build node refuses to
// write if live state has drifted from that.
//
// Evidence: in the 7,262-string human-attested Thai corpus, each current entry
// was followed in 0% of occurrences. The entries are over-specified or simply
// the wrong word, so following them would produce wrong Thai.
const GLOSS_PID = '46552447679363c70f7ef8.58193285';
const TH_LANG_ID = 753;

const CORRECTIONS = [
  // id, term, expected current Thai, corrected Thai, evidence
  [7173914, 'Report', 'รายงานปัญหา', 'รายงาน',   '0 of 123 used the glossary form; 121 used รายงาน. Entry means "report a problem".'],
  [7176115, 'About',  'เกี่ยวกับเรา', 'เกี่ยวกับ', '0 of 59 used the glossary form; 26 used เกี่ยวกับ. Entry means "about us"; a separate About us term exists.'],
  [7173862, 'Next',   'ต่อไป',       'ถัดไป',     '0 of 13 used ต่อไป; 7 used ถัดไป.'],
  [7173660, 'Back',   'ย้อนกลับ',     'กลับ',      '0 of 7 used ย้อนกลับ; 4 used กลับ. ย้อนกลับ reads as "revert".']
];

return [{ json: {
  write_mode: 'correct',
  project_id: GLOSS_PID,
  th_lang_id: TH_LANG_ID,
  terms: CORRECTIONS.map(function (c) {
    return { id: c[0], term: c[1], expect_current: c[2], thai: c[3], evidence: c[4] };
  }),
  read_url: 'https://api.lokalise.com/api2/projects/' + GLOSS_PID
    + '/glossary-terms?limit=500&pagination=cursor'
} }];

const plan = $('Plan').first().json;
const TH = Number(plan.th_lang_id);

// Fresh read. Snapshot comes from current state, never a cached file.
const live = {};
for (const p of $input.all()) {
  const r = p.json || {};
  const b = (r.body !== undefined) ? r.body : r;
  for (const t of (b.data || b.glossary_terms || [])) { live[String(t.id)] = t; }
}

const snapshot = [];
const payload = [];
const refused = [];

for (const want of plan.terms) {
  const t = live[String(want.id)];
  if (!t) { refused.push({ id: want.id, term: want.term, reason: 'term id not present in live glossary' }); continue; }
  if (String(t.term).trim() !== String(want.term).trim()) {
    refused.push({ id: want.id, expected: want.term, actual: t.term,
      reason: 'term text does not match the id - refusing to write' });
    continue;
  }
  const trs = t.translations || [];
  const th = trs.filter(function (x) { return Number(x.langId) === TH; });
  const current = th.length ? String(th[0].translation || '').trim() : '';

  if (want.expect_current !== undefined && want.expect_current !== null) {
    // Overwrite mode: only proceed if live state is exactly what was reviewed.
    if (current !== String(want.expect_current).trim()) {
      refused.push({ id: want.id, term: want.term,
        reason: 'live Thai differs from the value this correction was approved against - refusing to overwrite',
        expected_current: want.expect_current, actual_current: current });
      continue;
    }
  } else {
    // Fill mode: never clobber an existing value.
    if (current !== '') {
      refused.push({ id: want.id, term: want.term, reason: 'Thai already populated - refusing to overwrite', current: current });
      continue;
    }
  }

  snapshot.push({ id: t.id, term: t.term, th_before: current, th_after_intended: want.thai,
    evidence: want.evidence || '',
    languages_before: trs.length,
    nonempty_before: trs.filter(function (x) { return String(x.translation || '').trim() !== ''; }).length,
    all_before: trs.map(function (x) { return { langId: Number(x.langId),
      translation: x.translation || '', description: x.description || '' }; }) });

  payload.push({ id: t.id, translations: [{ langId: TH, translation: want.thai, description: '' }] });
}

return [{ json: {
  write_mode: plan.write_mode, project_id: plan.project_id,
  glossary_terms_live: Object.keys(live).length,
  requested: plan.terms.length, writable: payload.length,
  refused: refused, snapshot: snapshot, payload: { terms: payload },
  put_url: 'https://api.lokalise.com/api2/projects/' + plan.project_id + '/glossary-terms',
  read_url: plan.read_url } }];

// Independent re-read. Confirms Thai now holds the corrected value and that no
// other language changed. Also reads the errors array inside the 200 response -
// the earlier Thai write passed its status check while silently rejecting a term.
const build = $('Snapshot and payload').first().json;
const put = $('PUT glossary').first().json;
const TH = 753;

const putBody = (put && put.body !== undefined) ? put.body : (put || {});
const apiErrors = (putBody && putBody.errors) || [];
const meta = (putBody && putBody.meta) || {};

const live = {};
for (const p of $input.all()) {
  const r = p.json || {};
  const b = (r.body !== undefined) ? r.body : r;
  for (const t of (b.data || b.glossary_terms || [])) { live[String(t.id)] = t; }
}

function tr(t, id) {
  const hit = (t.translations || []).filter(function (x) { return Number(x.langId) === id; });
  return hit.length ? String(hit[0].translation || '') : '';
}

const results = [];
let ok = 0, bad = 0, collateral = 0;

for (const snap of build.snapshot) {
  const t = live[String(snap.id)];
  const after = t ? tr(t, TH).trim() : '';
  const lost = [];
  if (t) {
    for (const before of snap.all_before) {
      const lid = Number(before.langId);
      if (lid === TH) continue;
      if (String(before.translation || '').trim() === '') continue;
      if (tr(t, lid).trim() !== String(before.translation).trim()) {
        lost.push({ langId: lid, before: before.translation, after: tr(t, lid) });
      }
    }
  }
  const good = after === String(snap.th_after_intended).trim();
  if (good) ok++; else bad++;
  if (lost.length) collateral++;
  results.push({ id: snap.id, term: snap.term,
    th_before: snap.th_before, th_after: after, intended: snap.th_after_intended,
    corrected: good, other_languages_damaged: lost.length, damage: lost.slice(0, 5),
    evidence: snap.evidence });
}

const verdict = (apiErrors.length > 0) ? 'API RETURNED ERRORS - see api_errors'
  : (collateral > 0) ? 'COLLATERAL DAMAGE - restore from snapshot'
  : (bad > 0) ? 'Some corrections did not land'
  : 'CLEAN - all corrections applied, no other language touched';

return [{ json: { verdict: verdict,
  http_status: put ? put.statusCode : null,
  meta_updated: meta.updated !== undefined ? meta.updated : null,
  api_error_count: apiErrors.length, api_errors: apiErrors.slice(0, 20),
  attempted: build.snapshot.length, corrected_ok: ok, failed: bad,
  terms_with_collateral_damage: collateral,
  refused: build.refused, results: results } }];
